# --- PARSING ---

# Find all top-level POI blocks: from `  {` after the array start to `},\n  {` boundary.
# Easier: split by `\n  {\n    id:`.
poi_blocks = []
# Header up to and including 'export const ... = ['
header_end = text.find('[\n')
header = text[:header_end+2]
body = text[header_end+2:]

# Find every "  {\n    id:" occurrence, then take from there to the matching close.
# Use the fact that each block ends with one of: '}, image: "..."}\n' OR '}\n  },\n' OR '}\n  }\n];\n'
# Tactically: split at lines that match exactly '  },' or '  }' followed by '  {' or '];'

# Simpler: find ID positions, then text between consecutive IDs is a block.
id_pattern = re.compile(r'    id:\s*"([^"]+)"')
matches = list(id_pattern.finditer(text))
print(f"Found {len(matches)} POIs")

# Build new file
out_lines = []
out_lines.append("// @ts-nocheck")
out_lines.append('import type { POI } from "./poi";')
out_lines.append("")
out_lines.append("export const poiExtraGambiaCitiesV2: POI[] = [")

# For each POI, extract original fields then write clean block
for i, m in enumerate(matches):
    poi_id = m.group(1)
    start = m.start()
    # find next id or end
    if i+1 < len(matches):
        end = matches[i+1].start()
    else:
        end = text.find("];", start)
    block = text[start:end]

    # Extract fields
    def grab(pattern, default=""):
        mm = re.search(pattern, block, re.DOTALL)
        return mm.group(1) if mm else default

    poi_type = grab(r'type:\s*"([^"]+)"')
    parent = grab(r'parent:\s*"([^"]+)"')
    coords = grab(r'coords:\s*(\[[^\]]+\])')
    name_block = grab(r'name:\s*(\{[^}]+\})')

    # description: 4-lang short
    desc_block = grab(r'description:\s*\{\s*(de:\s*"[^"]*",?\s*hu:\s*"[^"]*",?\s*ro:\s*"[^"]*",?\s*en:\s*"[^"]*"\s*)')
    # parse out de/hu/ro/en
    def parse_lang_strings(s):
        result = {}
        for lang in ["de", "hu", "ro", "en"]:
            mm = re.search(rf'{lang}:\s*"((?:[^"\\]|\\.)*)"', s)
            result[lang] = mm.group(1) if mm else ""
        return result

    desc = parse_lang_strings(desc_block)

    # facts: 4-lang short - find top-level facts (not factsAdvanced)
    facts_match = re.search(r'\n    facts:\s*\{\s*(de:\s*\[[^\]]+\],?\s*hu:\s*\[[^\]]+\],?\s*ro:\s*\[[^\]]+\],?\s*en:\s*\[[^\]]+\])', block)
    facts_str = facts_match.group(1) if facts_match else ""
    def parse_lang_arrays(s):
        result = {}
        for lang in ["de", "hu", "ro", "en"]:
            mm = re.search(rf'{lang}:\s*(\[[^\]]+\])', s)
            result[lang] = mm.group(1) if mm else "[]"
        return result
    facts = parse_lang_arrays(facts_str)

    # Find ALL descriptionAdvanced blocks, pick longest content per lang
    # Pattern: descriptionAdvanced: { ... } - need balanced braces; use non-greedy to next factsAdvanced
    da_blocks = re.findall(r'descriptionAdvanced:\s*\{((?:[^{}]|\{[^}]*\})*?)\}', block, re.DOTALL)
    desc_adv = {"de": "", "hu": "", "ro": "", "en": ""}
    for db in da_blocks:
        parsed = parse_lang_strings(db)
        for lang, val in parsed.items():
            if val and len(val) > len(desc_adv[lang]) and "Dies ist eine" not in val and "Ez egy leírás" not in val and "Aceasta este o descriere" not in val and "This is a description" not in val:
                desc_adv[lang] = val

    # factsAdvanced
    fa_blocks = re.findall(r'factsAdvanced:\s*\{((?:[^{}]|\{[^}]*\})*?)\}', block, re.DOTALL)
    facts_adv = {"de": "[]", "hu": "[]", "ro": "[]", "en": "[]"}
    for fb in fa_blocks:
        parsed_arr = parse_lang_arrays(fb)
        for lang, val in parsed_arr.items():
            if val and len(val) > len(facts_adv[lang]) and '"Tény 1"' not in val and '"Fapt 1"' not in val and '"Fact 1"' not in val:
                facts_adv[lang] = val

    # Override HU with our hand-written content if available and existing is short
    if poi_id in HU_DESC and len(desc_adv["hu"]) < 50:
        desc_adv["hu"] = HU_DESC[poi_id]
    if poi_id in HU_FACTS and (facts_adv["hu"] == "[]" or '"Tény 1"' in facts_adv["hu"]):
        arr_str = "[" + ", ".join(f'"{x}"' for x in HU_FACTS[poi_id]) + "]"
        facts_adv["hu"] = arr_str

    # image
    img_match = re.search(r'image:\s*"([^"]+)"', block)
    image = img_match.group(1) if img_match else ""

    # If any lang in desc_adv still <50 char, fall back to a simple expansion of the short description
    for lang in ["de", "hu", "ro", "en"]:
        if len(desc_adv[lang]) < 50:
            # Use the short description as fallback
            desc_adv[lang] = desc[lang]

    # ensure every fact array has 6+ items, fall back to short facts if missing
    for lang in ["de", "hu", "ro", "en"]:
        if facts_adv[lang] == "[]" or len(facts_adv[lang]) < 30:
            facts_adv[lang] = facts.get(lang, "[]")

    # Build clean block
    def esc(s):
        return s.replace("\\", "\\\\").replace('"', '\\"')

    out_lines.append("  {")
    out_lines.append(f'    id: "{poi_id}",')
    out_lines.append(f'    type: "{poi_type}",')
    out_lines.append(f'    parent: "{parent}",')
    out_lines.append(f'    coords: {coords},')
    out_lines.append(f'    name: {name_block},')
    out_lines.append(f'    description: {{')
    out_lines.append(f'      de: "{esc(desc["de"])}",')
    out_lines.append(f'      hu: "{esc(desc["hu"])}",')
    out_lines.append(f'      ro: "{esc(desc["ro"])}",')
    out_lines.append(f'      en: "{esc(desc["en"])}"')
    out_lines.append(f'    }},')
    out_lines.append(f'    facts: {{')
    out_lines.append(f'      de: {facts["de"]},')
    out_lines.append(f'      hu: {facts["hu"]},')
    out_lines.append(f'      ro: {facts["ro"]},')
    out_lines.append(f'      en: {facts["en"]}')
    out_lines.append(f'    }},')
    out_lines.append(f'    descriptionAdvanced: {{')
    out_lines.append(f'      de: "{esc(desc_adv["de"])}",')
    out_lines.append(f'      hu: "{esc(desc_adv["hu"])}",')
    out_lines.append(f'      ro: "{esc(desc_adv["ro"])}",')
    out_lines.append(f'      en: "{esc(desc_adv["en"])}"')
    out_lines.append(f'    }},')
    out_lines.append(f'    factsAdvanced: {{')
    out_lines.append(f'      de: {facts_adv["de"]},')
    out_lines.append(f'      hu: {facts_adv["hu"]},')
    out_lines.append(f'      ro: {facts_adv["ro"]},')
    out_lines.append(f'      en: {facts_adv["en"]}')
    if image:
        out_lines.append(f'    }},')
        out_lines.append(f'    image: "{image}"')
    else:
        out_lines.append(f'    }}')
    out_lines.append("  }" + ("," if i+1 < len(matches) else ""))

out_lines.append("];")
out_lines.append("")

FILE.write_text("\n".join(out_lines), encoding="utf-8")
print(f"Wrote {len(matches)} POIs")

# Validate min char counts
warnings = 0
text2 = FILE.read_text(encoding="utf-8")
for poi_id_check in HU_DESC:
    pat = re.compile(rf'id:\s*"{re.escape(poi_id_check)}"[\s\S]*?descriptionAdvanced:\s*\{{[\s\S]*?\}}', re.DOTALL)
    mm = pat.search(text2)
    if mm:
        for lang in ["de", "hu", "ro", "en"]:
            mlang = re.search(rf'{lang}:\s*"((?:[^"\\]|\\.)*)"', mm.group(0))
            if mlang and len(mlang.group(1)) < 600:
                warnings += 1
                print(f"WARNING: {poi_id_check}.{lang} = {len(mlang.group(1))} chars")
print(f"Total <600 char warnings: {warnings}")
